import{_ as t,o as r,c as o,a1 as a}from"./chunks/framework.DdbKPUhY.js";const p=JSON.parse('{"title":"Router API Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/router-api.md","filePath":"spec/router-api.md"}'),i={name:"spec/router-api.md"};function n(s,e,d,l,u,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="router-api-spec" tabindex="-1">Router API Spec <a class="header-anchor" href="#router-api-spec" aria-label="Permalink to &quot;Router API Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Router module maps HTTP request paths and methods to handler functions. It supports two routing strategies: array-based (for small route sets) and trie-based (for large route sets with prefix matching). Transition between the two modes is automatic.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-router-new" tabindex="-1">uvhttp_router_new <a class="header-anchor" href="#uvhttp-router-new" aria-label="Permalink to &quot;uvhttp_router_new&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_router_new(uvhttp_router_t** router)</code></li><li><strong>Purpose</strong>: Create a new router instance</li><li><strong>Preconditions</strong>: <code>router</code> must be a non-NULL pointer to <code>uvhttp_router_t*</code></li><li><strong>Postconditions</strong>: On success, <code>*router</code> points to a valid router with <code>route_count=0</code>, <code>use_trie=0</code>, <code>array_routes=NULL</code>, <code>node_pool=NULL</code>.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>router</code> is NULL</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-router-free" tabindex="-1">uvhttp_router_free <a class="header-anchor" href="#uvhttp-router-free" aria-label="Permalink to &quot;uvhttp_router_free&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_router_free(uvhttp_router_t* router)</code></li><li><strong>Purpose</strong>: Free all router resources</li><li><strong>Preconditions</strong>: <code>router</code> must be valid (from <code>uvhttp_router_new</code>). Can be NULL (no-op).</li><li><strong>Postconditions</strong>: All memory is freed. The router pointer is invalid after return.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-router-add-route" tabindex="-1">uvhttp_router_add_route <a class="header-anchor" href="#uvhttp-router-add-route" aria-label="Permalink to &quot;uvhttp_router_add_route&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_router_add_route(uvhttp_router_t* router, const char* path, uvhttp_request_handler_t handler)</code></li><li><strong>Purpose</strong>: Add a route for all HTTP methods</li><li><strong>Preconditions</strong>: <code>router</code> must be valid. <code>path</code> must be non-NULL. <code>handler</code> must be non-NULL.</li><li><strong>Postconditions</strong>: The route is added to the router. If the route count exceeds the array threshold, automatic migration to trie mode occurs.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>router</code>, <code>path</code>, or <code>handler</code> is NULL</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure</li><li><code>UVHTTP_ERROR_NOT_FOUND</code>: route count exceeds MAX_ROUTES</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-router-add-route-method" tabindex="-1">uvhttp_router_add_route_method <a class="header-anchor" href="#uvhttp-router-add-route-method" aria-label="Permalink to &quot;uvhttp_router_add_route_method&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_router_add_route_method(uvhttp_router_t* router, const char* path, uvhttp_method_t method, uvhttp_request_handler_t handler)</code></li><li><strong>Purpose</strong>: Add a route for a specific HTTP method</li><li><strong>Preconditions</strong>: Same as <code>uvhttp_router_add_route</code>, plus <code>method</code> must be a valid <code>uvhttp_method_t</code>.</li><li><strong>Postconditions</strong>: Same as <code>uvhttp_router_add_route</code>, but the route is only matched for the specified method.</li><li><strong>Error conditions</strong>: Same as <code>uvhttp_router_add_route</code>.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-router-find-handler" tabindex="-1">uvhttp_router_find_handler <a class="header-anchor" href="#uvhttp-router-find-handler" aria-label="Permalink to &quot;uvhttp_router_find_handler&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_request_handler_t uvhttp_router_find_handler(const uvhttp_router_t* router, const char* path, const char* method)</code></li><li><strong>Purpose</strong>: Find the handler for a given path and method</li><li><strong>Preconditions</strong>: <code>router</code> must be valid. <code>path</code> must be non-NULL. <code>method</code> must be a valid HTTP method string.</li><li><strong>Postconditions</strong>: Returns the matching handler, or NULL if no match is found.</li><li><strong>Thread safety</strong>: Thread-safe for reads after all routes are added.</li></ul><h3 id="uvhttp-router-match" tabindex="-1">uvhttp_router_match <a class="header-anchor" href="#uvhttp-router-match" aria-label="Permalink to &quot;uvhttp_router_match&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_router_match(const uvhttp_router_t* router, const char* path, const char* method, uvhttp_route_match_t* match)</code></li><li><strong>Purpose</strong>: Match a path and extract path parameters</li><li><strong>Preconditions</strong>: Same as <code>uvhttp_router_find_handler</code>, plus <code>match</code> must be non-NULL.</li><li><strong>Postconditions</strong>: On success, <code>match-&gt;handler</code> is set, <code>match-&gt;params</code> contains extracted parameters, <code>match-&gt;param_count</code> is set.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: any argument is NULL</li><li><code>UVHTTP_ERROR_NOT_FOUND</code>: no matching route</li></ul></li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h2 id="route-path-syntax" tabindex="-1">Route Path Syntax <a class="header-anchor" href="#route-path-syntax" aria-label="Permalink to &quot;Route Path Syntax&quot;">​</a></h2><ul><li><code>/users</code> — exact match</li><li><code>/users/:id</code> — parameter match (extracts <code>id</code> from path segment)</li><li><code>/static/*</code> — prefix match (matches any path starting with <code>/static/</code>)</li><li><code>/api/v1/users</code> — static prefix with multiple segments</li></ul><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>Array mode</strong>: Routes are stored in a flat array. Matching is O(n) linear scan. Used when route count is below the migration threshold.</p></li><li><p><strong>Trie mode</strong>: Routes are stored in a compact prefix trie (128-byte nodes). Matching is O(k) where k is the path length. Used after automatic migration.</p></li><li><p><strong>Automatic migration</strong>: When the route count exceeds the array threshold (default: 8), the array is migrated to a trie. Migration is transparent: all routes remain functional.</p></li><li><p><strong>Parameter extraction</strong>: Path parameters (<code>:param</code>) are extracted during matching. Parameters are stored in <code>uvhttp_route_match_t::params</code>.</p></li><li><p><strong>Wildcard routes</strong>: The <code>*</code> wildcard matches any path prefix. Wildcard routes have the lowest priority.</p></li><li><p><strong>Method matching</strong>: When a route is added with a specific method, only requests with that method match. Routes added without a method match all methods.</p></li><li><p><strong>Fallback handler</strong>: If set, the fallback handler is called when no route matches. The fallback handler is the last resort before returning 404.</p></li></ol><h2 id="performance-requirements" tabindex="-1">Performance Requirements <a class="header-anchor" href="#performance-requirements" aria-label="Permalink to &quot;Performance Requirements&quot;">​</a></h2><ul><li>Array mode matching: O(n) where n = route count</li><li>Trie mode matching: O(k) where k = path segment count</li><li>Route addition: O(1) amortized (array mode), O(k) (trie mode)</li><li>Node size: 128 bytes (2 cache lines)</li><li>Memory: ~128 bytes per route (trie mode), ~512 bytes per route (array mode)</li><li>Migration: automatic, transparent</li></ul><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Route addition (all methods, specific methods, wildcard, parameter)</li><li>Route matching (exact, prefix, parameter, method-specific)</li><li>Non-matching routes return NULL handler</li><li>Array-to-trie migration</li><li>NULL parameter handling for all public functions</li><li>Maximum route count enforcement</li><li>Parameter extraction correctness</li><li>Fallback handler behavior</li><li>Static file route registration</li><li>Memory cleanup (no leaks on free)</li></ul>',24)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
